//go:build js && wasm

package main

import (
	"sort"
	"strings"
	"syscall/js"

	"urlnote/goback/shared"
)

// ---- dictionary word suggestions (IME-style completion) ----
// The word lists are generated by scripts/gen_suggest_dicts.py and served
// from /dict/.

var suggestZH []string
var suggestJA []string

// preloadSuggestDicts kicks off the fetches once; lookups are no-ops until a
// list arrives.
func preloadSuggestDicts() {
	loadSuggestList(BASE_PATH + "/dict/suggest_zh.txt")
	loadSuggestList(BASE_PATH + "/dict/suggest_ja.txt")
}

func loadSuggestList(url string) {
	go func() {
		resp := fetchDo("GET", url, nil, nil)
		if !resp.Get("ok").Bool() {
			return
		}
		text := await(resp.Call("text")).String()
		var words []string
		for _, line := range strings.Split(text, "\n") {
			if w := strings.TrimSpace(line); w != "" {
				words = append(words, w)
			}
		}
		sort.Strings(words)
		// dedupe
		out := words[:0]
		for i, w := range words {
			if i == 0 || w != words[i-1] {
				out = append(out, w)
			}
		}
		if strings.Contains(url, "_ja.") {
			suggestJA = out
		} else {
			suggestZH = out
		}
	}()
}

func prefixLookup(words []string, prefix string, limit int, isJA bool, out *[]suggestItem) {
	if words == nil {
		return
	}
	idx := sort.SearchStrings(words, prefix)
	for i := idx; i < len(words) && i < idx+limit; i++ {
		if !strings.HasPrefix(words[i], prefix) {
			break
		}
		*out = append(*out, suggestItem{word: words[i], isJA: isJA})
	}
}

func isCJKChar(r rune) bool {
	return (r >= 0x4e00 && r <= 0x9fff) ||
		(r >= 0x3040 && r <= 0x30ff) ||
		(r >= 0xf900 && r <= 0xfaff)
}

func isWordChar(r rune) bool {
	return r == '_' || (r >= '0' && r <= '9') || (r >= 'a' && r <= 'z') ||
		(r >= 'A' && r <= 'Z') || r >= 0x80
}

// lookupSuggestions returns up to 8 completions (4 Chinese + 4 Japanese).
func lookupSuggestions(fragment string) []suggestItem {
	out := []suggestItem{}
	prefixLookup(suggestZH, fragment, 4, false, &out)
	prefixLookup(suggestJA, fragment, 4, true, &out)
	return out
}

func (a *App) closeSuggestions() {
	if len(a.suggestItems) > 0 {
		a.suggestItems = a.suggestItems[:0]
		renderSuggestPanel()
	}
	a.suggestAnchor = jsUndefined()
}

// updateSuggestions reads the word fragment typed before the cursor and
// refreshes the suggestion panel.
func (a *App) updateSuggestions() {
	if a.applyingRemote || !a.canEdit {
		a.closeSuggestions()
		return
	}
	sel := js.Global().Call("getSelection")
	if !sel.Truthy() || !sel.Get("isCollapsed").Bool() {
		a.closeSuggestions()
		return
	}
	node := sel.Get("anchorNode")
	if !node.Truthy() || node.Get("nodeType").Int() != 3 { // TEXT_NODE
		a.closeSuggestions()
		return
	}
	offset := sel.Get("anchorOffset").Int()
	text := node.Get("textContent").String()
	chars := []rune(text)
	if offset > len(chars) {
		a.closeSuggestions()
		return
	}
	// walk backwards over word characters (CJK or alnum)
	start := offset
	for start > 0 && isWordChar(chars[start-1]) {
		start--
	}
	fragment := string(chars[start:offset])
	// stay hidden right after accepting: the accepted word itself would
	// re-trigger the panel at the same cursor position
	if a.suggestAcceptedWord != "" {
		if a.suggestAcceptedWord == fragment {
			a.closeSuggestions()
			return
		}
		a.suggestAcceptedWord = ""
	}
	hasCJK := strings.IndexFunc(fragment, isCJKChar) >= 0
	if !hasCJK || fragment == "" || len([]rune(fragment)) > 8 {
		a.closeSuggestions()
		return
	}
	items := lookupSuggestions(fragment)
	if len(items) == 0 {
		a.closeSuggestions()
		return
	}
	// position the panel at the cursor (viewport coords + position:fixed)
	posL, posT := 40, 40
	if sel.Get("rangeCount").Int() > 0 {
		r := sel.Call("getRangeAt", 0).Call("getBoundingClientRect")
		posL = int(r.Get("left").Float())
		posT = int(r.Get("bottom").Float()) + 4
	}
	a.suggestAnchor = node
	a.suggestAnchorStart = start
	a.suggestAnchorEnd = offset
	a.suggestActive = 0
	a.suggestPos = [2]int{posL, posT}
	a.suggestItems = items
	renderSuggestPanel()
}

func renderSuggestPanel() {
	a := app
	old := qs(".suggest-panel")
	if old.Truthy() {
		old.Call("remove")
	}
	if len(a.suggestItems) == 0 {
		return
	}
	panel := el("div", map[string]any{
		"class": "suggest-panel",
		"style": "left:" + itoa(a.suggestPos[0]) + "px; top:" + itoa(a.suggestPos[1]) + "px;",
	})
	on(panel, "mousedown", func(e jsValue) { e.Call("preventDefault") })
	for i, item := range a.suggestItems {
		idx := i
		it := item
		row := el("div", map[string]any{"class": "suggest-item"})
		row.Call("appendChild", el("span", map[string]any{"class": "suggest-word"}, it.word))
		langCls := "suggest-lang"
		lang := "中"
		if it.isJA {
			langCls = "suggest-lang ja"
			lang = "日"
		}
		row.Call("appendChild", el("span", map[string]any{"class": langCls}, lang))
		on(row, "mouseenter", func(e jsValue) {
			a.suggestActive = idx
			renderSuggestActive()
		})
		on(row, "click", func(e jsValue) { a.acceptSuggestion(idx) })
		panel.Call("appendChild", row)
	}
	renderSuggestActiveInto(panel)
	a.editorWrapParent().Call("appendChild", panel)
}

func renderSuggestActiveInto(panel jsValue) {
	rows := panel.Get("children")
	for i := 0; i < rows.Length(); i++ {
		if i == app.suggestActive {
			rows.Index(i).Get("classList").Call("add", "active")
		} else {
			rows.Index(i).Get("classList").Call("remove", "active")
		}
	}
}

func renderSuggestActive() {
	p := qs(".suggest-panel")
	if p.Truthy() {
		renderSuggestActiveInto(p)
	}
}

func (a *App) onSuggestKeydown(key string) {
	if len(a.suggestItems) == 0 {
		return
	}
	n := len(a.suggestItems)
	switch key {
	case "ArrowDown":
		a.suggestActive = (a.suggestActive + 1) % n
		renderSuggestActive()
	case "ArrowUp":
		a.suggestActive = (a.suggestActive + n - 1) % n
		renderSuggestActive()
	case "Enter", "Tab":
		a.acceptSuggestion(a.suggestActive)
	case "Escape":
		a.closeSuggestions()
	}
}

// acceptSuggestion replaces the typed fragment with the chosen word.
func (a *App) acceptSuggestion(idx int) {
	if idx < 0 || idx >= len(a.suggestItems) {
		return
	}
	item := a.suggestItems[idx]
	anchor := a.suggestAnchor
	start, end := a.suggestAnchorStart, a.suggestAnchorEnd
	a.closeSuggestions()
	if !anchor.Truthy() {
		return
	}
	sel := js.Global().Call("getSelection")
	range_ := doc().Call("createRange")
	range_.Call("setStart", anchor, start)
	range_.Call("setEnd", anchor, end)
	sel.Call("removeAllRanges")
	sel.Call("addRange", range_)
	// insertValue collapses the selection and inserts at its start —
	// delete the selected fragment first
	a.editor.deleteValue()
	a.editor.insertValue(item.word, true)
	a.suggestAcceptedWord = item.word
	a.markDirty()
}

// ---- grammar analysis drawer ----

func (a *App) runAnalysis() {
	if a.analyzeBusy {
		return
	}
	a.analyzeBusy = true
	a.analyzeOpen = true
	renderAnalyzeDrawer()
	go func() {
		content := a.editor.getValue()
		var d shared.AnalyzeResponse
		ok := fetchJSON("POST", apiURL("/api/analyze"), shared.AnalyzeRequest{Content: content}, &d)
		a.analyzeBusy = false
		if !ok {
			a.setStatus("分析失败", "error")
			renderAnalyzeDrawer()
			return
		}
		a.analyzeIssues = d.Issues
		a.analyzeApplied = map[int]bool{}
		if len(d.Issues) == 0 {
			a.setStatus("分析完成:未发现明显问题", "saved")
		} else {
			a.setStatus("分析完成", "saved")
		}
		renderAnalyzeDrawer()
	}()
}

func renderAnalyzeDrawer() {
	a := app
	old := qs(".analyze-drawer")
	if old.Truthy() {
		old.Call("remove")
	}
	if !a.analyzeOpen {
		return
	}
	drawer := el("div", map[string]any{"class": "analyze-drawer"})
	on(drawer, "mousedown", func(e jsValue) { e.Call("stopPropagation") })
	head := el("div", map[string]any{"class": "analyze-head"})
	if a.analyzeBusy {
		head.Call("appendChild", el("strong", nil, "分析中…"))
	} else if n := len(a.analyzeIssues); n == 0 {
		head.Call("appendChild", el("strong", nil, "词法分析"))
	} else {
		head.Call("appendChild", el("strong", nil, "词法分析 · "+itoa(n)+" 个问题"))
	}
	closeBtn := el("button", map[string]any{"type": "button", "class": "tool"}, "关闭")
	on(closeBtn, "click", func(e jsValue) {
		a.analyzeOpen = false
		renderAnalyzeDrawer()
	})
	head.Call("appendChild", closeBtn)
	drawer.Call("appendChild", head)
	body := el("div", map[string]any{"class": "analyze-body"})
	if len(a.analyzeIssues) == 0 {
		msg := "未发现明显问题 ✅"
		if a.analyzeBusy {
			msg = "正在分析…"
		}
		body.Call("appendChild", el("p", map[string]any{"class": "analyze-empty"}, msg))
	}
	for idx, it := range a.analyzeIssues {
		issue := it
		i := idx
		div := el("div", map[string]any{"class": "analyze-issue"})
		quote := issue.Quote
		if quote == "" {
			quote = "—"
		}
		div.Call("appendChild", el("div", map[string]any{"class": "issue-quote"}, quote))
		div.Call("appendChild", el("div", map[string]any{"class": "issue-problem"}, issue.Problem))
		if issue.Suggestion != "" {
			div.Call("appendChild", el("div", map[string]any{"class": "issue-fix"}, "建议: "+issue.Suggestion))
		}
		if issue.Start != issue.End {
			btn := el("button", map[string]any{"type": "button", "class": "tool issue-apply"}, "应用到编辑器")
			if a.analyzeApplied[i] {
				btn.Set("disabled", true)
				btn.Set("textContent", "已应用")
			}
			on(btn, "click", func(e jsValue) { a.applyIssue(i) })
			div.Call("appendChild", btn)
		}
		body.Call("appendChild", div)
	}
	drawer.Call("appendChild", body)
	a.editorWrapParent().Call("appendChild", drawer)
}

// applyIssue applies an issue's suggestion by char-offset replacement.
func (a *App) applyIssue(idx int) {
	if idx < 0 || idx >= len(a.analyzeIssues) {
		return
	}
	issue := a.analyzeIssues[idx]
	if issue.Start == issue.End {
		return // whole-text warning, nothing to replace
	}
	current := a.editor.getValue()
	chars := []rune(current)
	if issue.End > len(chars) {
		a.setStatus("内容已变化,请重新分析", "error")
		return
	}
	next := string(chars[:issue.Start]) + issue.Suggestion + string(chars[issue.End:])
	a.editor.setValue(next)
	a.analyzeApplied[idx] = true
	a.markDirty()
	a.save()
	// later issue offsets are now stale — shift them by the delta
	delta := len([]rune(issue.Suggestion)) - (issue.End - issue.Start)
	for i := range a.analyzeIssues {
		if i != idx && a.analyzeIssues[i].Start >= issue.End {
			a.analyzeIssues[i].Start = max0(a.analyzeIssues[i].Start + delta)
			a.analyzeIssues[i].End = max0(a.analyzeIssues[i].End + delta)
		}
	}
	renderAnalyzeDrawer()
}

func max0(n int) int {
	if n < 0 {
		return 0
	}
	return n
}
